"""Plain-language context and remediation for individual web findings."""

INFO = {
    "SQLI": ("SQL injection", "CWE-89", "A changed input produced a repeatable database error.", "Queries may mix user input with SQL, potentially allowing unauthorized reads or changes.", "Use parameterized queries for every input and restrict database account permissions.", "Error evidence does not establish data access, authentication bypass or write access."),
    "SQLI_BOOLEAN": ("Blind SQL injection", "CWE-89", "Two distinct true/false pairs changed a stable response consistently.", "An input may influence SQL conditions even when the database hides errors.", "Use prepared statements and avoid building SQL conditions from request strings.", "Response differences are candidates until database behavior is independently verified."),
    "XSS": ("Reflected cross-site scripting", "CWE-79", "A unique payload appeared in an active HTML context.", "If a browser executes the reflected code, an attacker may act within the application's origin.", "Apply context-appropriate output encoding; use safe DOM APIs and a restrictive CSP.", "The scanner does not execute JavaScript or demonstrate a CSP bypass."),
    "LFI": ("File inclusion / traversal", "CWE-22", "File signatures appeared only after a traversal probe and repeated.", "An input may allow reading files outside the intended application directory.", "Map inputs to an allowlist of server-side files and reject resolved paths outside the allowed directory.", "The check demonstrates signatures; it does not establish access to arbitrary files or code execution."),
    "CORS": ("Credentialed cross-origin policy", "CWE-942", "Controlled origins were accepted with credential permission.", "A hostile website may read responses if a browser can send a useful authenticated session.", "Allowlist exact trusted origins, reject null unless required, and enable credentials only where needed.", "Authenticated sensitive data exposure and browser cookie policies still need verification."),
    "OPEN_REDIRECT": ("Open redirect", "CWE-601", "Two external hosts influenced a redirect destination.", "A trusted application URL can send a user to an attacker-controlled destination.", "Accept relative paths or allowlist exact destinations after canonical URL parsing.", "Redirect acceptance alone does not demonstrate credential theft or an OAuth bypass."),
    "HOST_HEADER": ("Host-header injection", "CWE-346", "Controlled Host or X-Forwarded-Host values influenced generated URL hosts.", "Untrusted host values may affect security-sensitive links or redirects.", "Use a configured canonical origin, validate allowed hosts and trust forwarded headers only from approved proxies.", "Password-reset or cache-poisoning impact was not tested."),
    "EXPOSED_FILE": ("Exposed application file", "CWE-552", "The response matched a known configuration, source, repository or archive structure.", "Public source or configuration can disclose implementation details and may contain credentials.", "Remove sensitive files from the document root, block repository/configuration paths and rotate any exposed credentials.", "Signatures establish exposure candidates; intended public downloads may be legitimate. Contents are omitted."),
    "DIR_LISTING": ("Directory listing", "CWE-548", "An index heading and multiple child-file links were observed.", "A directory index may reveal files that were not intended to be discoverable.", "Disable directory indexing and review permissions for each downloadable file.", "A listing may be intentional; access to listed files was not automatically tested."),
    "DIR": ("Discovered web path", "", "A response differed from randomized missing-path controls.", "This is an inventory observation rather than a demonstrated vulnerability.", "Review whether this endpoint and its authentication behavior are intended.", "A successful, protected or redirecting path is not itself a vulnerability."),
    "ERROR_DISCLOSURE": ("Detailed error disclosure", "CWE-209", "A server error included a recognizable stack-trace structure.", "Detailed errors can reveal internal paths, frameworks and implementation behavior.", "Return a generic public error and send details only to access-controlled server logs.", "Trace contents are omitted; no exploitation of the disclosed information was attempted."),
    "DEBUG_DISCLOSURE": ("Public diagnostic page", "CWE-215", "A response matched a framework debug page or phpinfo diagnostic page.", "Diagnostic pages may expose environment information or security-sensitive configuration.", "Disable production debug mode and remove or restrict diagnostic endpoints.", "The check does not retain environment values or establish a separate exploit path."),
    "TLS_PROTOCOL": ("Obsolete TLS protocol", "CWE-327", "An exact-version handshake negotiated TLS 1.0 or TLS 1.1.", "Legacy protocol support expands exposure to obsolete cryptography.", "Disable TLS 1.0/1.1 and enable TLS 1.2/1.3 with an appropriate cipher policy.", "This is a protocol support check, not a complete cipher audit."),
    "TLS_CERTIFICATE": ("Certificate validity or identity", "CWE-295", "The certificate's dates or subject alternative names failed an identity/validity check.", "Clients may reject the connection or be unable to authenticate the intended endpoint.", "Install a currently valid certificate with the correct DNS/IP subject alternative names.", "Certificate revocation and every possible certificate chain were not checked."),
    "TLS_TRUST": ("Certificate trust advisory", "CWE-295", "Validation failed against the scanner's local CA trust store.", "Public clients may reject the connection; a private CA can also explain this result.", "Serve the required chain and configure trusted clients with the correct CA where appropriate.", "Private CA usage is not automatically a vulnerability."),
    "TRACE_ENABLED": ("HTTP TRACE enabled", "", "Two TRACE requests echoed a request line and a unique header.", "TRACE adds unnecessary request-echo functionality on many production deployments.", "Disable TRACE unless an explicit operational requirement exists.", "No cookies or authorization headers were sent; credential theft was not demonstrated."),
    "HTTP_METHODS": ("Advertised HTTP methods", "", "OPTIONS advertised additional methods.", "Capability advertisement requires review of authentication and authorization.", "Disable unneeded methods and verify access controls on required write endpoints.", "PUT, DELETE, PATCH and CONNECT were not exercised; Allow alone is not proof of write access."),
    "WEB_CONFIG": ("Response protection advisory", "", "A response header or cookie attribute was missing or invalid.", "The response may lack a browser-side protection appropriate to its purpose.", "Review the specific header or cookie flag in the evidence and apply the appropriate policy.", "Headers and cookie flags depend on application needs; missing protection does not prove exploitability."),
    "CORS_CONFIG": ("Invalid CORS credential policy", "", "Wildcard origin permission was combined with credentials.", "Browsers reject credentialed reads with this combination; the configuration may be unintended.", "Use explicit trusted origins for credentialed CORS, or omit credentials for public wildcard access.", "This configuration is an advisory, not proof of cross-origin credential exposure."),
}


def describe_finding(result):
    title, cwe, detection, impact, remediation, limitations = INFO.get(result["type"], INFO["WEB_CONFIG"])
    references = [{"title": "OWASP Web Security Testing Guide", "url": "https://wstg.owasp.org/v4.2/4-Web_Application_Security_Testing/"}]
    if cwe:
        references.append({"title": cwe, "url": f"https://cwe.mitre.org/data/definitions/{cwe.split('-')[1]}.html"})
    return {"title": title, "cwe": cwe, "detection": detection, "impact": impact,
            "remediation": remediation, "limitations": limitations,
            "verification_steps": ["Review the recorded baseline and probe requests.",
                                   "Run the PoC against the same endpoint and compare the expected evidence.",
                                   "Review application context and browser behavior where noted.",
                                   "Repeat the check after applying the fix."], "references": references}
